        },
        "aesthetic": {
          "type": "array",
          "items": {
            "type": "string",
            "enum": ["cyberpunk", "steampunk", "vaporwave", "synthwave", "noir", "minimalist", "maximalist", "gothic", "baroque", "retro_80s", "vintage_50s", "futuristic", "post_apocalyptic", "ethereal", "dreamcore", "weirdcore"]
          }
        },
